from itertools import combinations
def transform(g):
    H,W=len(g),len(g[0])
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]]
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    # convex hull (monotone chain), lower then upper
    P=sorted(set(pts))
    if len(P)<=2: hull=P
    else:
        lower=[]
        for p in P:
            while len(lower)>=2 and cross(lower[-2],lower[-1],p)<=0: lower.pop()
            lower.append(p)
        upper=[]
        for p in reversed(P):
            while len(upper)>=2 and cross(upper[-2],upper[-1],p)<=0: upper.pop()
            upper.append(p)
        hull=lower[:-1]+upper[:-1]
    def inside(p):  # strictly inside or on hull-edge interior
        n=len(hull); sign=0
        for i in range(n):
            o,a,b=hull[i],hull[(i+1)%n],hull[(i+2)%n]
        # use winding: point in convex polygon (allow boundary)
        vals=[cross(hull[i],hull[(i+1)%n],p) for i in range(n)]
        if any(v<0 for v in vals) and any(v>0 for v in vals): return False
        return True
    out=[row[:] for row in g]
    for r in range(H):
